class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        lo, hi = 0, m * n - 1               # 当成长度 m·n 的有序数组
        while lo <= hi:
            mid = (lo + hi) // 2
            x = matrix[mid // n][mid % n]   # 一维下标换回行列
            if x == target:
                return True
            if x < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return False

