class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length, n = matrix[0].length;
        int lo = 0, hi = m * n - 1;                     // 当成长度 m·n 的有序数组
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int x = matrix[mid / n][mid % n];           // 一维下标换回行列
            if (x == target) {
                return true;
            }
            if (x < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return false;
    }
